= [top rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@" "]];		if (r1.location == NSNotFound) {			r1 = NSMakeRange(top.length-2,1);		}		NSRange r2 = [bot rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@"ATCGatcg"]];		if (r2.location == NSNotFound) {			r2 = NSMakeRange( bot.length-2, 1);		}		mid1 = min(r1.location, r2.location);		mid2 = max(r1.location, r2.location);		leftRemove = NSMakeRange(3, 0);		leftRemove.length = max(mid1 - 3 - shownPerSide, 0);		mid1 -= leftRemove.length;		mid2 -= leftRemove.length;		rightRemove = NSMakeRange(0, 0);		rightRemove.location = min(mid2 + shownPerSide, top.length - leftRemove.length);		rightRemove.length = top.length - leftRemove.length - rightRemove.location - 2;		if(rightRemove.length > top.length - rightRemove.location) rightRemove.length = 0;	}		NSMutableAttributedString * ss = [[NSMutableAttributedString alloc] initWithString: [NSString stringWithFormat: @"\r%@\r", jname]];	[ss appendAttributedString:[self abridge:topString left:leftRemove right:rightRemove]];	[ss appendAttributedString:retrn];	[ss appendAttributedString:[self abridge:leftMatchString left:leftRemove right:rightRemove]];	[ss appendAttributedString:retrn];	[ss appendAttributedString:[self abridge:midString left:leftRemove right:rightRemove]];	[ss appendAttributedString:retrn];	[ss appendAttributedString:[self abridge:rightMatchString left:leftRemove right:rightRemove]];	[ss appendAttributedString:retrn];	[ss appendAttributedString:[self abridge:botString left:leftRemove right:rightRemove]];	[ss appendAttributedString:retrn];		alignmentString = [ss copy];		if(fillerRange.length == 0) fillerRange.location = 0;	if(microRange.length == 0) microRange.location = 0;	fillerRange = NSIntersectionRange(fillerRange, NSMakeRange(0, midString.length)); // Because sometimes fillerRange is too big	self.microhomology = [[midString string] substringWithRange: microRange];	self.filler = [[midString string] substringWithRange:fillerRange];	self.nmicro = [NSNumber numberWithInt:microRange.length];	self.nfiller = [NSNumber numberWithInt:fillerRange.length];	self.nmissingLeft = [NSNumber numberWithInt:missingLeftRange.length];	self.nmissingRight = [NSNumber numberWithInt:missingRightRange.length];		[myDoc appendOutputA:alignmentString];		if (fillerTemplate > 0) {			NSString * direction = @"forward";			if (fillerTemplate == 2) direction = @"reverse";			[myDoc appendOutput: [NSString stringWithFormat: @"\rMatch template for ""%@"" (%@) :  ", jname, direction]];			[myDoc appendOutputA:fillerMatchString];			[myDoc appendOutput: @"\r"];					}	}@end